/* ---------------- layout helpers (fractions of the trim box) ---------------- */
const txt=(text,o)=>({type:'text',text:String(text),align:'center',...o});
const rect=(x,y,w,h,color,o={})=>({type:'rect',x,y,w,h,color,...o});
const ell=(x,y,w,h,color,o={})=>({type:'circle',x,y,w,h,color,...o});
const shp=(shape,x,y,w,h,color,o={})=>({type:'shape',shape,x,y,w,h,color,...o});
const hline=(x,y,w,color,st=.006)=>({type:'line',x,y,w,color,st});
// square helpers keep proportions on any aspect ratio; d = fraction of the short side
const sq=(c,cx,cy,d)=>({x:cx-d*c.mn/c.W/2,y:cy-d*c.mn/c.H/2,w:d*c.mn/c.W,h:d*c.mn/c.H});
const icon=(c,shape,cx,cy,d,color,o={})=>{const b=sq(c,cx,cy,d);return shp(shape,b.x,b.y,b.w,b.h,color,o);};
const dot=(c,cx,cy,d,color,o={})=>{const b=sq(c,cx,cy,d);return ell(b.x,b.y,b.w,b.h,color,o);};
const th_=(size,c,lines=1)=>size*c.mn*(1.25+1.2*(lines-1))/c.H; // height of a text block (fraction of H)
const nl=s=>String(s).split('\n').length;
// vertical stack of text items: [text, opts] with opts.size; returns layers and the final y
function stack(c,y,items){const out=[];for(const [text,o] of items){if(text==null){y+=o.gap||0;continue;}out.push(txt(text,{...o,y}));y+=th_(o.size,c,nl(text))+(o.gap??0);}return {out,y};}
const stackH=(c,items)=>items.reduce((h,[text,o])=>h+(text==null?(o.gap||0):th_(o.size,c,nl(text))+(o.gap??0)),0);
const centerStack=(c,cy,items)=>stack(c,cy-stackH(c,items)/2,items).out;
// contact lines with small icons; align left (icons before text) or center (text only)
function contacts(c,th,x,y,size,color,{iconColor,align='left',lines=['phone','email','web'],gap=.55,maxW=.5}={}){const out=[];const lh=th_(size,c)*(1+gap);const ic={phone:'phone',email:'mail',web:'globe',address:'pin'};for(const k of lines){const v=CONTACT[k];if(align==='left'&&iconColor){const d=size*1.05;out.push(icon(c,ic[k],x+d*c.mn/c.W/2,y+th_(size,c)/2,d,iconColor));out.push(txt(v,{x:x+d*c.mn/c.W*1.7,y,size,font:th.body,color,align:'left',maxW}));}else out.push(txt(v,{x,y,size,font:th.body,color,align,maxW}));y+=lh;}return out;}
const lum=h=>{const n=parseInt(h.slice(1),16);return ((n>>16)*299+((n>>8)&255)*587+(n&255)*114)/1000;};
const onDark=h=>lum(h)<140;

/* ---------------- product families ---------------- */
export function templateFamily(product){const id=product.id;if(product.group==='Apparel')return /hats/.test(id)?'hat':'apparel';if(product.views)return 'vehicle';
 return {'business-cards':'card','flyers':'print','postcards':'print','brochures':'brochure','door-hangers':'hanger','roll-up-banner':'tall','x-frame-banner':'tall','flags':'flag','vinyl-banners':'wide','yard-signs':'sign','a-frame-signs':'sign'}[id]||'print';}

