   ...stack(c,.16,[[th.copy.person,{x:.46,size:.105,font:th.head,bold:th.hb,color:th.ink===('#ffffff')?'#141414':th.ink,align:'left',maxW:.5,gap:.01}],[th.copy.role,{x:.46,size:.052,font:th.body,color:th.muted,align:'left',maxW:.5}]]).out,
